class Counter {
public:
    int next() {
        count += 1;
        return count;
    }

private:
    int count = 0;
};

struct Point {
    int x;
    int y;
};

struct Bound {
    int& target;
};

void use(Bound& bound) {
    Counter counter;
    Counter other = counter;
    Point point;
    Point origin = point;
    Bound alias = bound;
}

